mapper.select:
    	select CASH_ID
		from FIN_CASH_INFO
		where FINPROD_ID = #{FINPROD_ID,jdbcType=VARCHAR} 
			and CASH_TYPE_2 = #{CASH_TYPE_2,jdbcType=VARCHAR}
			and BRANCH = 0

mapper.delete:
		delete from FIN_CASH_PLAN
        where CASH_ID = #{cashId,jdbcType=VARCHAR}
          and MDATE >= #{mdate,jdbcType=DATE}
